using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CorruptAction", menuName = "Data/Battle/Battle Actions/Purification Actions/Corrupt Action")]
public class CorruptAction : BattleAction
{
	[Header("Player Effects List")]
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	private bool ignoreResetWickedCard;

	public void ResetIgnoreResetWickedCard()
	{
		ignoreResetWickedCard = false;
	}

	public void CastTargetAmountForAreaConfuse(GameObject target, int purifyAmount, GameObject source)
	{
		ignoreResetWickedCard = true;
		CastTargetAmount(target, purifyAmount, source);
	}

	public override void CastTargetAmount(GameObject target, int corruptAmount, GameObject source)
	{
		SingleTargetCast(target, corruptAmount, source);
	}

	private void SingleTargetCast(GameObject target, int corruptAmount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		ActivateOnCorruptAfflictionSingleTimeOmens(corruptAmount, source);
		IncreaseApianSkyfallAmount(source);
		corruptAmount = CheckCorruptCritical(corruptAmount, source);
		corruptAmount = CheckCorruptedEnhanceOnPlayer(corruptAmount, source);
		PlaySFX();
		EnterActionQueueState();
		DefaultCast(target, corruptAmount, source, corruptionPurifyModifierEnum);
		if (!ignoreResetWickedCard)
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		}
	}

	private void EnterActionQueueState()
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.ActionsQueueState.EnqueueNormalPurifyCorruptCoroutineAction();
		instance.SetState(instance.ActionsQueueState);
	}

	public void CastTargetAmountPierce(GameObject target, int corruptAmount, GameObject source)
	{
		SingleTargetCast(target, corruptAmount, source, CorruptionPurifyModifierEnum.PIERCE);
	}

	public void CastTargetAmountXTime(GameObject target, int corruptAmount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		ActivateOnCorruptAfflictionSingleTimeOmens(corruptAmount, source);
		IncreaseApianSkyfallAmount(source);
		corruptAmount = CheckCorruptCritical(corruptAmount, source);
		corruptAmount = CheckCorruptedEnhanceOnPlayer(corruptAmount, source);
		PlaySFX();
		DefaultCast(target, corruptAmount, source, corruptionPurifyModifierEnum);
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int corruptAmount, GameObject source)
	{
		AreaTargetCast(targets, corruptAmount, source);
	}

	private void AreaTargetCast(List<GameObject> targets, int corruptAmount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		ActivateOnCorruptAfflictionSingleTimeOmens(corruptAmount, source);
		IncreaseApianSkyfallAmount(source);
		corruptAmount = CheckCorruptCritical(corruptAmount, source);
		corruptAmount = CheckCorruptedEnhanceOnPlayer(corruptAmount, source);
		PlaySFX();
		EnterActionQueueState();
		for (int i = 0; i < targets.Count; i++)
		{
			DefaultCast(targets[i], corruptAmount, source, corruptionPurifyModifierEnum);
		}
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
	}

	public void AreaCastTargetAmountPierce(List<GameObject> targets, int corruptAmount, GameObject source)
	{
		AreaTargetCast(targets, corruptAmount, source, CorruptionPurifyModifierEnum.PIERCE);
	}

	public void AreaCastTargetAmountXTime(List<GameObject> targets, int corruptAmount, GameObject source)
	{
		ActivateOnCorruptAfflictionSingleTimeOmens(corruptAmount, source);
		IncreaseApianSkyfallAmount(source);
		corruptAmount = CheckCorruptCritical(corruptAmount, source);
		corruptAmount = CheckCorruptedEnhanceOnPlayer(corruptAmount, source);
		PlaySFX();
		for (int i = 0; i < targets.Count; i++)
		{
			DefaultCast(targets[i], corruptAmount, source);
		}
	}

	private int CheckCorruptCritical(int corruptAmount, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source))
		{
			PlayerEffects component = source.GetComponent<PlayerEffects>();
			if (component.IsPlayerCriticalIridescentLightAndCorruptComesFromConfuse())
			{
				return component.IsPlayerCriticalCheckCritical(corruptAmount, fierceSquall: false, sentPur: false);
			}
			if (component.IsPlayerFierceSquall(activateFeedback: false))
			{
				return component.IsPlayerCriticalCheckCritical(corruptAmount, fierceSquall: true, sentPur: false);
			}
		}
		else if (ReferenceSingleton<BattleHandler>.Instance.IsSourceEnemy(source))
		{
			return source.GetComponent<CorruptedAnimalEffects>().IsEnemyCriticalCorruptionCheckCritical(corruptAmount);
		}
		return corruptAmount;
	}

	private int CheckCorruptedEnhanceOnPlayer(int corruptAmount, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && corruptAmount == 1)
		{
			PlayerEffects component = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();
			if (component.IsCorruptedEnhanceActiveAndDecreaseEffect())
			{
				corruptAmount = component.GetCorruptedEnhanceEffect().NewCorruptionValue;
			}
		}
		return corruptAmount;
	}

	private void IncreaseApianSkyfallAmount(GameObject source)
	{
		if (!ReferenceSingleton<BattleHandler>.Instance.IsSourceEnemy(source) && source != null)
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.ApianSkyFallAmount++;
		}
	}

	private void ActivateOnCorruptAfflictionSingleTimeOmens(int corruptAmount, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) || ReferenceSingleton<BattleHandler>.Instance.IsSourceCompanions(source))
		{
			ReferenceSingleton<SothisOmensHandler>.Instance.ActivateOnCorruptAfflictionSingleTimeOmens(corruptAmount);
		}
	}

	private void DefaultCast(GameObject target, int corruptAmount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		if (corruptionPurifyModifierEnum != CorruptionPurifyModifierEnum.CANTBEINCREASEDCORRUPTION && ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>().IsEffectActive(playerEffectsList.FrenzyActiveEffect, activateFeedback: false))
		{
			corruptAmount *= 2;
		}
		SpawnVFX(GetVFXOwnerPosition(target), 3f);
		target.GetComponent<CorruptionStats>().Corrupt(corruptAmount, source, corruptionPurifyModifierEnum);
		ReferenceSingleton<MiscOmensHandler>.Instance.WickedsCardOmenAction?.Invoke(source, target);
		if (!ReferenceSingleton<BattleHandler>.Instance.IsSourceEnemy(source) && source != null)
		{
			if (ReferenceSingleton<BattleHandler>.Instance.IsTargetEnemy(target))
			{
				ReferenceSingleton<MiscOmensHandler>.Instance.ActivateOnCorruptEnemyOmens(target, corruptAmount);
				ReferenceSingleton<SothisOmensHandler>.Instance.ActivateOnCorruptAfflictionEnemyMultipleTimesOmens(corruptAmount);
			}
			ReferenceSingleton<MiscOmensHandler>.Instance.ActivateOnCorruptOmens(target, source, corruptAmount);
		}
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) || ReferenceSingleton<BattleHandler>.Instance.IsSourceCompanions(source))
		{
			ReferenceSingleton<SothisOmensHandler>.Instance.ActivateOnCorruptAfflictionMultipleTimesOmens(target, corruptAmount);
		}
	}
}
